using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "HeveliusModifierScoreXPItemData", menuName = "Data/ScoreXP/HeveliusModifierScoreXPItemData", order = 0)]
public class HeveliusModifierScoreXPItemData : ScoreXPItemData
{
	[SerializeField]
	private Character hevelius;

	[SerializeField]
	private float multiplier;

	public override int GetScoreXPItemValue()
	{
		return (int)((float)base.GetScoreXPItemValue() * ((ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter == hevelius) ? multiplier : 1f));
	}
}
